INSERT OR IGNORE INTO recipe_steps VALUES(416,18,0,'In the one pot, add 1/4 cup toor dal and rinse it',12,15);
INSERT OR IGNORE INTO recipe_steps VALUES(417,18,1,'Add 4 washed tomatos',17,20);
INSERT OR IGNORE INTO recipe_steps VALUES(418,18,2,'Add turmeric, 1 tsp oil',21,24);
INSERT OR IGNORE INTO recipe_steps VALUES(419,18,3,'Add 1 tbsp jaggery, 1 tbsp tamarind concentrate',0,0);
INSERT OR IGNORE INTO recipe_steps VALUES(420,18,4,'enough water to submerge at least half tomatoes',25,28);
INSERT OR IGNORE INTO recipe_steps VALUES(421,18,5,'Let the pressure go away, peel tomato skin, and mash',35,58);
INSERT OR IGNORE INTO recipe_steps VALUES(422,18,6,'Add 4 cups of water',60,63);
INSERT OR IGNORE INTO recipe_steps VALUES(423,18,7,'Add Salt 1 tbsp, few curry leaves, 3 tbsp rasam powder, and mix well',63,87);
INSERT OR IGNORE INTO recipe_steps VALUES(424,18,8,'Boil 2 more minutes',90,393);
INSERT OR IGNORE INTO recipe_steps VALUES(425,18,9,'Prepare tempering: heat oil, add mustard, cumin seeds, hing, red chilies, curry leaves',99,119);
INSERT OR IGNORE INTO recipe_steps VALUES(426,18,10,'Pour tempering into rasam',120,123);
INSERT OR IGNORE INTO recipe_steps VALUES(427,18,11,'Add coriander leaves',123,127);
INSERT OR IGNORE INTO recipe_steps VALUES(428,18,12,'Serve with rice',0,0);
INSERT OR IGNORE INTO recipe_steps VALUES(471,19,0,'Rinse the rice thoroughly and soak in water for 20-30 minutes.',0,0);
INSERT OR IGNORE INTO recipe_steps VALUES(472,19,1,'Heat 4 tbsp cooking oil and 2 tbsp ghee in a pressure cooker.',14,20);
INSERT OR IGNORE INTO recipe_steps VALUES(473,19,2,'Add the whole spices: bay leaves, stone flower, cinnamon, cardamom, cloves, mace, fennel seeds, kapok buds, and kasuri methi. Saute till aromatic.',24,40);
INSERT OR IGNORE INTO recipe_steps VALUES(474,19,3,'Add 1 sliced onion and saute till translucent.',44,58);
INSERT OR IGNORE INTO recipe_steps VALUES(475,19,4,'Add 200g diced mushrooms and saute for a few minutes.',64,88);
INSERT OR IGNORE INTO recipe_steps VALUES(476,19,5,'Meanwhile, grind coriander leaves, mint leaves, green chillies, ginger, garlic, and tomatoes with a little water into a smooth green paste.',94,128);
INSERT OR IGNORE INTO recipe_steps VALUES(477,19,6,'Add the ground green paste, turmeric powder, and garam masala powder to the mushrooms. Mix well and cook for a couple of minutes.',144,158);
INSERT OR IGNORE INTO recipe_steps VALUES(478,19,7,'Add curd and mix.',184,194);
INSERT OR IGNORE INTO recipe_steps VALUES(479,19,8,'Add water and salt; bring to a boil.',224,250);
INSERT OR IGNORE INTO recipe_steps VALUES(480,19,9,'Add the soaked rice and mix gently.',274,288);
INSERT OR IGNORE INTO recipe_steps VALUES(481,19,10,'Boil for 5 minutes on high flame.',288,300);
INSERT OR IGNORE INTO recipe_steps VALUES(482,19,11,'Cover and pressure cook until the rice is done, then let the pressure release naturally.',300,310);
INSERT OR IGNORE INTO recipe_steps VALUES(483,19,12,'Open the lid and fluff the rice gently with a fork.',310,350);
INSERT OR IGNORE INTO recipe_steps VALUES(484,19,13,'Serve hot with onion raita.',370,385);
