INSERT OR IGNORE INTO recipes VALUES(17,8,'South Indian Vegetable Sambar',4,unistr('Quick mixed-vegetable sambar in a pressure cooker (~15 min). Tempering (mustard, urad dal, dried red chilli, hing, curry leaves) is added at the end.\u000a\u000aSource: https://hebbarskitchen.com/south-indian-vegetable-sambar-recipe/'),1782771618,NULL);
