INSERT OR IGNORE INTO recipes VALUES(19,8,'Mushroom Biryani',4,unistr('Kannada-style mushroom dum biryani: whole spices bloomed in oil-ghee, mushrooms and onion sauteed, simmered in a ground coriander-mint-green chilli masala with curd, then rice cooked in with it. Serve with onion raita.\u000a\u000aSource: https://www.youtube.com/watch?v=FgrpkWqDVMQ (Rekha Aduge)'),1786304147,60);
